INSERT INTO posts (id, author_id, category_id, title, slug, excerpt, content, featured_image, featured_image_alt, status, visibility, is_featured, is_trending, views, reading_time, meta_title, meta_description, published_at, created_at) VALUES (1, 1, 1, 'The quiet architecture behind fast PHP applications', 'how-to-build-a-modern-php-website', 'Speed is rarely a plugin. It is a set of boring decisions made before the first feature ships.', '<p>A fast PHP site is usually a small one. Not small in ambition, small in the number of times it touches the database, the disk, and the network before a reader sees a headline.</p><h2>Start with the query, not the cache</h2><p>Teams reach for Redis because a page feels slow, then discover the page was running the same lookup twelve times. Count the queries on the homepage before you add a cache key. If a section needs three posts per category, fetch them together.</p><p>Prepared statements are not only a security control. They also make it obvious which values are data and which values are structure. Keep limits and offsets as integers you interpolate after casting. Bind everything a visitor typed.</p><ul><li>Index the columns you sort and filter on.</li><li>Select only the columns a card needs.</li><li>Attach tags in one follow-up query, not one query per card.</li></ul><blockquote><p>If the homepage makes a request for every card, the design is more expensive than it looks.</p></blockquote><h2>Render less, carefully</h2><p>Images should declare their size, lazy-load below the fold, and live behind a cache header. The article itself can stay dynamic. Readers notice a late hero image more than they notice a perfectly cached footer.</p><pre><code class="language-php">$stmt = $pdo-&gt;prepare(&#039;SELECT id, title, slug FROM posts WHERE status = ? LIMIT 6&#039;);
