INSERT INTO posts (id, author_id, category_id, title, slug, excerpt, content, featured_image, featured_image_alt, status, visibility, is_featured, is_trending, views, reading_time, meta_title, meta_description, published_at, created_at) VALUES (2, 3, 1, 'What serious teams get wrong about AI assistants', 'what-serious-teams-get-wrong-about-ai', 'The useful question is not whether the model is clever. It is which decisions you still want a person to own.', '<p>Most AI rollouts fail in the same place: a team automates a task nobody had defined. The assistant produces confident paragraphs, the review step disappears, and the work gets worse while the dashboard says adoption is up.</p><h2>Keep a human on the last mile</h2><p>Drafting is a good job for a model. Publishing is not. A newsroom can ask for a headline list, an outline, or a tighter lede, then an editor still has to decide what is true and what is merely plausible.</p><ul><li>Write down the decision the tool is not allowed to make.</li><li>Store the source of every claim a draft relies on.</li><li>Measure correction time, not just generation time.</li></ul><blockquote><p>An assistant that cannot be disagreed with is just a faster way to be wrong.</p></blockquote><p>The teams that get value treat the model as a junior colleague with a short memory. They give it a narrow brief, they check the work, and they keep the byline attached to a person.</p>', '/assets/images/covers/02.jpg', 'What serious teams get wrong about AI assistants', 'published', 'public', 1, 1, 2210, 1, 'What serious teams get wrong about AI assistants', 'The useful question is not whether the model is clever. It is which decisions you still want a person to own.', DATE_SUB(NOW(), INTERVAL 4 DAY), DATE_SUB(NOW(), INTERVAL 4 DAY));
INSERT INTO post_tags (post_id, tag_id) VALUES (2, 3);
INSERT INTO post_tags (post_id, tag_id) VALUES (2, 6);
INSERT INTO posts (id, author_id, category_id, title, slug, excerpt, content, featured_image, featured_image_alt, status, visibility, is_featured, is_trending, views, reading_time, meta_title, meta_description, published_at, created_at) VALUES (3, 2, 1, 'A practical SEO checklist for editorial sites', 'practical-seo-checklist-for-editorial-sites', 'Search traffic still comes from pages that are specific, fast, and unwilling to compete with themselves.', '<p>Editorial SEO is less mysterious than the plugin market suggests. Each story needs one URL, one title that a person would say out loud, and a description that matches the piece.</p><h2>One address per story</h2><p>Duplicate paths are how publications leak authority. If a story lives at /blog/the-slug, it should not also answer at /post.php?id=14. Canonical tags help. Redirects are better. Clean routes are best.</p><ul><li>Write a unique title and meta description.</li><li>Add article and breadcrumb structured data.</li><li>Put real pages in the sitemap and keep drafts out.</li><li>Paginate with stable URLs.</li></ul><p>Internal links should point at the category, the author, and two related stories a reader might actually want. A block of forty tag links is not a strategy.</p>', '/assets/images/covers/03.jpg', 'A practical SEO checklist for editorial sites', 'published', 'public', 0, 1, 1633, 1, 'A practical SEO checklist for editorial sites', 'Search traffic still comes from pages that are specific, fast, and unwilling to compete with themselves.', DATE_SUB(NOW(), INTERVAL 6 DAY), DATE_SUB(NOW(), INTERVAL 6 DAY));
INSERT INTO post_tags (post_id, tag_id) VALUES (3, 4);
INSERT INTO post_tags (post_id, tag_id) VALUES (3, 12);
INSERT INTO posts (id, author_id, category_id, title, slug, excerpt, content, featured_image, featured_image_alt, status, visibility, is_featured, is_trending, views, reading_time, meta_title, meta_description, published_at, created_at) VALUES (4, 4, 2, 'Why your startup does not need another dashboard', 'why-your-startup-does-not-need-another-dashboard', 'A new chart rarely fixes a fuzzy decision. Most early teams need fewer numbers and a shorter meeting.', '<p>The second dashboard is usually a sign that the first one did not change anyone&#039;s behavior. Founders add a chart when they are afraid to pick a priority.</p><h2>Decide what would change your week</h2><p>If a metric cannot change what you ship on Monday, it does not belong on the wall. Revenue, activation, and the one operational number that keeps the product honest are enough for a long time.</p><blockquote><p>A dashboard is a report. A decision is a meeting you were willing to end.</p></blockquote><p>Build the instrument after the question is stable. Until then, a spreadsheet and a written weekly note will tell you more than a wall of charts nobody opens.</p>', '/assets/images/covers/04.jpg', 'Why your startup does not need another dashboard', 'published', 'public', 0, 0, 980, 1, 'Why your startup does not need another dashboard', 'A new chart rarely fixes a fuzzy decision. Most early teams need fewer numbers and a shorter meeting.', DATE_SUB(NOW(), INTERVAL 9 DAY), DATE_SUB(NOW(), INTERVAL 9 DAY));
INSERT INTO post_tags (post_id, tag_id) VALUES (4, 5);
INSERT INTO post_tags (post_id, tag_id) VALUES (4, 6);
INSERT INTO posts (id, author_id, category_id, title, slug, excerpt, content, featured_image, featured_image_alt, status, visibility, is_featured, is_trending, views, reading_time, meta_title, meta_description, published_at, created_at) VALUES (5, 1, 2, 'The case for boring business models', 'the-case-for-boring-business-models', 'Subscriptions, services, and unglamorous margins still beat a story that only works in a pitch.', '<p>Boring is not the same as small. A company that invoices the same customers every month can plan. A company that needs a new story every quarter cannot.</p><h2>Margin is a product decision</h2><p>The model shows up in the writing, the hiring, and the support queue. If the only way the numbers work is a future price increase nobody has agreed to, the model is a wish.</p><ul><li>Know who pays and why they stay.</li><li>Prefer revenue you can explain without a footnote.</li><li>Leave room for support, because trust is part of the cost.</li></ul><p>Readers can smell a business that exists to be acquired. The more interesting companies can describe a customer, a price, and a reason the relationship continues.</p>', '/assets/images/covers/05.jpg', 'The case for boring business models', 'published', 'public', 1, 0, 1422, 1, 'The case for boring business models', 'Subscriptions, services, and unglamorous margins still beat a story that only works in a pitch.', DATE_SUB(NOW(), INTERVAL 12 DAY), DATE_SUB(NOW(), INTERVAL 12 DAY));
INSERT INTO post_tags (post_id, tag_id) VALUES (5, 6);
INSERT INTO post_tags (post_id, tag_id) VALUES (5, 5);
INSERT INTO posts (id, author_id, category_id, title, slug, excerpt, content, featured_image, featured_image_alt, status, visibility, is_featured, is_trending, views, reading_time, meta_title, meta_description, published_at, created_at) VALUES (6, 4, 4, 'How founders should read a term sheet', 'how-founders-should-read-a-term-sheet', 'The valuation is the loud number. Control, preference, and the option pool are the ones that change your outcome.', '<p>A term sheet is a short document with a long memory. Founders fixate on the headline valuation because it is easy to repeat. The clauses around it decide who gets paid, and when.</p><h2>Read in this order</h2><ul><li>Liquidation preference and participation.</li><li>Who sits on the board.</li><li>The option pool, and whether it comes out of the pre-money number.</li><li>Protective provisions that can block a later sale.</li></ul><p>None of this is a reason to avoid outside capital. It is a reason to read slowly and to pay a lawyer who has seen the movie before. A friendly investor will not be offended by a careful founder.</p><blockquote><p>If you cannot explain the preference stack on a whiteboard, you do not know what you sold.</p></blockquote>', '/assets/images/covers/06.jpg', 'How founders should read a term sheet', 'published', 'public', 1, 1, 1765, 1, 'How founders should read a term sheet', 'The valuation is the loud number. Control, preference, and the option pool are the ones that change your outcome.', DATE_SUB(NOW(), INTERVAL 15 DAY), DATE_SUB(NOW(), INTERVAL 15 DAY));
INSERT INTO post_tags (post_id, tag_id) VALUES (6, 9);
INSERT INTO post_tags (post_id, tag_id) VALUES (6, 5);
INSERT INTO posts (id, author_id, category_id, title, slug, excerpt, content, featured_image, featured_image_alt, status, visibility, is_featured, is_trending, views, reading_time, meta_title, meta_description, published_at, created_at) VALUES (7, 5, 4, 'Personal cash flow for people who hate spreadsheets', 'personal-cash-flow-without-the-spreadsheet', 'You do not need a twelve-tab workbook. You need a number for what must be paid and a number for what can wait.', '<p>Personal finance advice often starts with a system elaborate enough to become a hobby. The useful version is smaller: money in, money that has a job, and money that does not.</p><h2>Three piles are enough</h2><p>One account pays the rent and the bills that would hurt if they slipped. One account is for the life you actually live. One account is for later, and you do not borrow from it because a weekend looked expensive.</p><p>Automate the transfers the day you are paid. The spreadsheet can wait until you are curious. The habit matters more than the template.</p>', '/assets/images/covers/07.jpg', 'Personal cash flow for people who hate spreadsheets', 'published', 'public', 0, 0, 860, 1, 'Personal cash flow for people who hate spreadsheets', 'You do not need a twelve-tab workbook. You need a number for what must be paid and a number for what can wait.', DATE_SUB(NOW(), INTERVAL 18 DAY), DATE_SUB(NOW(), INTERVAL 18 DAY));
INSERT INTO post_tags (post_id, tag_id) VALUES (7, 9);
INSERT INTO post_tags (post_id, tag_id) VALUES (7, 7);
INSERT INTO posts (id, author_id, category_id, title, slug, excerpt, content, featured_image, featured_image_alt, status, visibility, is_featured, is_trending, views, reading_time, meta_title, meta_description, published_at, created_at) VALUES (8, 3, 3, 'Designing a morning that survives real life', 'designing-a-morning-that-survives-real-life', 'The perfect routine collapses the first time a child, a train, or a deploy does not cooperate.', '<p>Morning routines are sold as personality. They work better as a short list of things that still happen when the day is rude.</p><h2>Protect one block, not the whole hour</h2><p>Pick a single action that makes the rest of the day less fragile. For some people that is writing before messages. For others it is a walk before the first meeting. The ritual can be twenty minutes. It cannot depend on silence, a special notebook, and nobody needing you.</p><blockquote><p>A routine you can keep on a bad Tuesday is the only one you have.</p></blockquote><p>Leave the rest of the morning flexible. The point is not to become a person in a video. The point is to arrive at the work already slightly on your own side.</p>', '/assets/images/covers/08.jpg', 'Designing a morning that survives real life', 'published', 'public', 0, 0, 740, 1, 'Designing a morning that survives real life', 'The perfect routine collapses the first time a child, a train, or a deploy does not cooperate.', DATE_SUB(NOW(), INTERVAL 21 DAY), DATE_SUB(NOW(), INTERVAL 21 DAY));
INSERT INTO post_tags (post_id, tag_id) VALUES (8, 7);
INSERT INTO posts (id, author_id, category_id, title, slug, excerpt, content, featured_image, featured_image_alt, status, visibility, is_featured, is_trending, views, reading_time, meta_title, meta_description, published_at, created_at) VALUES (9, 4, 5, 'The art of leaving a city you love', 'the-art-of-leaving-a-city-you-love', 'Remote work made it possible to go. It did not make the goodbye any cleaner.', '<p>Leaving a city is a practical project disguised as a feeling. You can book the flight and still be wrong about what you will miss.</p><h2>Take the map, not the myth</h2><p>Write down the places you actually use: the morning walk, the friend who will not move, the doctor, the desk by the window. A city is a set of repeating errands. If the next place cannot hold the errands that matter, the skyline will not save it.</p><p>Give yourself a return date even if you do not use it. People leave more honestly when the door is not slammed.</p>', '/assets/images/covers/09.jpg', 'The art of leaving a city you love', 'published', 'public', 0, 1, 1190, 1, 'The art of leaving a city you love', 'Remote work made it possible to go. It did not make the goodbye any cleaner.', DATE_SUB(NOW(), INTERVAL 25 DAY), DATE_SUB(NOW(), INTERVAL 25 DAY));
INSERT INTO post_tags (post_id, tag_id) VALUES (9, 8);
INSERT INTO posts (id, author_id, category_id, title, slug, excerpt, content, featured_image, featured_image_alt, status, visibility, is_featured, is_trending, views, reading_time, meta_title, meta_description, published_at, created_at) VALUES (10, 5, 5, 'A field guide to a slow weekend in Lisbon', 'a-slow-weekend-in-lisbon', 'Skip the checklist. The city is better as a sequence of neighborhoods than as a stack of monuments.', '<p>Lisbon rewards the traveler who picks a hill and stays with it. The light changes, the trams complain, and lunch runs long if you let it.</p><h2>A modest route</h2><ul><li>Morning coffee in a neighborhood you can walk without a map.</li><li>One museum, not three.</li><li>An afternoon by the river when the wind is up.</li><li>Dinner close enough to walk home.</li></ul><p>The mistake is treating the city as a trophy. It is a place to be slightly late. Pack shoes you can actually wear on tiled hills, and leave one meal unplanned.</p>', '/assets/images/covers/10.jpg', 'A field guide to a slow weekend in Lisbon', 'published', 'public', 0, 0, 690, 1, 'A field guide to a slow weekend in Lisbon', 'Skip the checklist. The city is better as a sequence of neighborhoods than as a stack of monuments.', DATE_SUB(NOW(), INTERVAL 28 DAY), DATE_SUB(NOW(), INTERVAL 28 DAY));
INSERT INTO post_tags (post_id, tag_id) VALUES (10, 8);
INSERT INTO post_tags (post_id, tag_id) VALUES (10, 7);
INSERT INTO posts (id, author_id, category_id, title, slug, excerpt, content, featured_image, featured_image_alt, status, visibility, is_featured, is_trending, views, reading_time, meta_title, meta_description, published_at, created_at) VALUES (11, 2, 2, 'Remote work is a management problem', 'remote-work-is-a-management-problem', 'The tool was never the hard part. Unclear ownership still shows up, it just shows up in a different window.', '<p>Companies blamed video calls for a problem they had in the office: nobody knew who was allowed to decide. Remote work made the gap visible because there was no hallway to patch it.</p><h2>Write the work down</h2><p>A distributed team needs a record of what good looks like, when something is due, and who is waiting. That is not bureaucracy. It is how you avoid a meeting whose only purpose is to reconstruct the last meeting.</p><blockquote><p>If the plan lives in someone&#039;s head, the company is closed whenever that person is asleep.</p></blockquote><p>Meet when a decision needs a voice. Write when the work needs a memory. The teams that do both stop arguing about whether remote work is real.</p>', '/assets/images/covers/11.jpg', 'Remote work is a management problem', 'published', 'public', 0, 1, 1544, 1, 'Remote work is a management problem', 'The tool was never the hard part. Unclear ownership still shows up, it just shows up in a different window.', DATE_SUB(NOW(), INTERVAL 32 DAY), DATE_SUB(NOW(), INTERVAL 32 DAY));
INSERT INTO post_tags (post_id, tag_id) VALUES (11, 8);
INSERT INTO post_tags (post_id, tag_id) VALUES (11, 6);
INSERT INTO posts (id, author_id, category_id, title, slug, excerpt, content, featured_image, featured_image_alt, status, visibility, is_featured, is_trending, views, reading_time, meta_title, meta_description, published_at, created_at) VALUES (12, 3, 1, 'JavaScript without the framework hangover', 'javascript-without-the-framework-hangover', 'A publication does not need a client-side application to show an essay. It needs a page that loads.', '<p>The modern default is to begin with a framework and then spend a year removing it from the critical path. For a reading site, start from the other end.</p><h2>Use the platform</h2><p>Forms can post. Fetch can enhance them. A navigation menu can be a button and a hidden element. None of that requires a build step, and all of it still works when the script is slow.</p><ul><li>Keep the article in HTML.</li><li>Enhance search, comments, and the newsletter.</li><li>Do not block the first paint on a bundle.</li></ul><p>Frameworks earn their place when the interface is an application. A story is not an application. Treat it like a document and the page gets quieter.</p>', '/assets/images/covers/12.jpg', 'JavaScript without the framework hangover', 'published', 'public', 0, 1, 1330, 1, 'JavaScript without the framework hangover', 'A publication does not need a client-side application to show an essay. It needs a page that loads.', DATE_SUB(NOW(), INTERVAL 36 DAY), DATE_SUB(NOW(), INTERVAL 36 DAY));
INSERT INTO post_tags (post_id, tag_id) VALUES (12, 2);
INSERT INTO post_tags (post_id, tag_id) VALUES (12, 12);
INSERT INTO posts (id, author_id, category_id, title, slug, excerpt, content, featured_image, featured_image_alt, status, visibility, is_featured, is_trending, views, reading_time, meta_title, meta_description, published_at, created_at) VALUES (13, 4, 1, 'Security habits every small team can afford', 'security-habits-every-small-team-can-afford', 'You do not need a security department to stop the mistakes that actually take sites down.', '<p>Small teams get breached in ordinary ways: a reused password, a file upload that was trusted, a query built with a string. The fixes are dull and they work.</p><h2>A short list that holds</h2><ul><li>Hash passwords with password_hash and verify them with password_verify.</li><li>Bind every query. Escape every string you print.</li><li>Regenerate the session when someone signs in.</li><li>Reject uploads that are not images, then re-encode the ones that are.</li><li>Put a token on every form that changes data.</li></ul><p>Rate-limit the sign-in form. Log the exception. Do not show the stack trace to a stranger. None of this is glamorous, which is why it gets skipped until the incident report.</p><blockquote><p>Security that depends on remembering to be careful will fail on a Friday.</p></blockquote>', '/assets/images/covers/13.jpg', 'Security habits every small team can afford', 'published', 'public', 0, 0, 2011, 1, 'Security habits every small team can afford', 'You do not need a security department to stop the mistakes that actually take sites down.', DATE_SUB(NOW(), INTERVAL 40 DAY), DATE_SUB(NOW(), INTERVAL 40 DAY));
INSERT INTO post_tags (post_id, tag_id) VALUES (13, 11);
INSERT INTO post_tags (post_id, tag_id) VALUES (13, 1);
INSERT INTO posts (id, author_id, category_id, title, slug, excerpt, content, featured_image, featured_image_alt, status, visibility, is_featured, is_trending, views, reading_time, meta_title, meta_description, published_at, created_at) VALUES (14, 3, 3, 'Building a design system people actually use', 'building-a-design-system-people-actually-use', 'A system is a set of decisions you stop relitigating. If nobody can find them, you do not have one.', '<p>Design systems fail when they are museums. The colors exist, the components exist, and every new page invents a third button because the first two were hard to find.</p><h2>Name the few things that repeat</h2><p>A publication needs type, space, a card, a button, and a form field. Document those with the real CSS variables. Add a component only after the second team asks for it.</p><p>Put the primary color in one place. If changing it means a hunt through a stylesheet, the system is a folder of screenshots.</p>', '/assets/images/covers/14.jpg', 'Building a design system people actually use', 'published', 'public', 0, 0, 910, 1, 'Building a design system people actually use', 'A system is a set of decisions you stop relitigating. If nobody can find them, you do not have one.', DATE_SUB(NOW(), INTERVAL 46 DAY), DATE_SUB(NOW(), INTERVAL 46 DAY));
INSERT INTO post_tags (post_id, tag_id) VALUES (14, 10);
