INSERT INTO posts (id, author_id, category_id, title, slug, excerpt, content, featured_image, featured_image_alt, status, visibility, is_featured, is_trending, views, reading_time, meta_title, meta_description, published_at, created_at) VALUES (15, 1, 2, 'The newsletter is not dead. The lazy one is.', 'the-newsletter-is-not-dead', 'People still open letters that sound like a person. They ignore the ones that sound like a funnel.', '<p>Inbox advice swings between funeral and gold rush. The truth is plainer. A letter with a point of view still gets read. A letter that exists to feed an ad slot does not.</p><h2>Write it like a note</h2><p>Pick a cadence you can keep. Say what you published and why it mattered. Leave the twelve-sponsor template for someone else. The signup form should promise exactly that, and the admin should be able to export the list without a ceremony.</p><blockquote><p>Frequency is a promise. Miss it on purpose or keep it. Do not apologize every week for a product you did not plan.</p></blockquote><p>Measure replies, not just opens. A list that argues with you is healthier than a list that never writes back.</p>', '/assets/images/covers/15.jpg', 'The newsletter is not dead. The lazy one is.', 'published', 'public', 0, 1, 1288, 1, 'The newsletter is not dead. The lazy one is.', 'People still open letters that sound like a person. They ignore the ones that sound like a funnel.', DATE_SUB(NOW(), INTERVAL 52 DAY), DATE_SUB(NOW(), INTERVAL 52 DAY));
